import{z as A,x as d,o,c as B,q as i,j as r,D as a,d as n,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Unicode 分词陷阱","description":"","frontmatter":{"title":"Unicode 分词陷阱","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/unicode-tokenization.md","filePath":"llm/unicode-tokenization.md","lastUpdated":1791063341000}'),D={name:"llm/unicode-tokenization.md"};function p(c,e,k,m,g,F){const E=d("Mermaid");return o(),B("div",null,[e[2]||(e[2]=i('<h1 id="unicode-分词陷阱" tabindex="-1">Unicode 分词陷阱 <a class="header-anchor" href="#unicode-分词陷阱" aria-label="Permalink to &quot;Unicode 分词陷阱&quot;">​</a></h1><div class="epigraph"><p>同一个「不」字，UTF-8 三字节、GBK 两字节：BPE 切完 token 数不同、账单不同、智力不同——Unicode 是分词器脚下最深的坑。</p><footer>—— 据 Petrov et al.「Language Model Tokenizers Introduce Unfairness」(2023)；Unicode TR#13 分行与 NFC 规范化</footer></div><p><a href="/llm/bpe-merge-rule">BPE 合并规则</a>讲词表大小，本课讲编码层：UTF-8 字节流进 BPE 之前，Unicode 本身已经埋了等价形、组合字符与方言码位三重坑。缺口是<strong>Unicode 分词陷阱</strong>——为什么同一个字符串换个写法 token 数就翻倍，以及工程上怎么防。本课不做编码学通识。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三重坑。<strong>等价形</strong>：「é」可是一个码位 U+00E9，也可拆成 e + 组合尖符 U+0301——视觉相同、字节不同、token 化不同，检索与评测双双错位。<strong>切分差异</strong>：中文、韩文在 UTF-8 是 3 字节/字，日文假名也是 3 字节，而 emoji 高达 4 字节——BPE 词表若以英语为主语料，非拉丁文本 fertility（字符/token 比）骤降。<strong>规范化不一致</strong>：NFC 与 NFD 产生的串在数据库里都不相等，遑论 token 相等。</p><p><span class="marginnote">术语翻译：fertility（生育率）= 平均每个 token 覆盖的字符数，越低越费 token；NFC/NFD = Unicode 规范化的组合式/分解式；Zalgo 文本 = 恶意叠加几十个组合符让单「字」膨胀成百字节。</span></p><p><span class="marginnote">数字实例：「é」NFC 单码位 2 字节，token 1 个；NFD 两码位 3 字节，常被切成 2–3 个 token。印地语天城文一个「字」由辅音 + 元音符号 + 组合符拼成，英语为主的 BPE 词表下 fertility 低到 0.3——同样一段话 token 数是英语的 3 倍多，API 账单与上下文窗口同步×3。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程防坑四件套：<strong>入口规范化统一</strong>（进 tokenizer 前 NFC + 统一大小写折叠）；<strong>字节回退兜底</strong>（GPT 式 byte-level BPE——任何字节序列都有 token 表示，永不 OOV，代价是罕见 Unicode 碎成字节）；<strong>按 Script 预切分</strong>（tiktoken 式正则把拉丁/汉字/数字/标点先分段，BPE 只在段内合并——防跨文字垃圾 token）；<strong>评测集 NFC 化</strong>（对比模型输出与参考答案前先归一化，否则 1 个 token 的差异污染评测）。</p>',9)),(o(),r(s,null,{default:a(()=>[l(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8E%9F%E5%A7%8B%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%20--%3E%20B%5B%22NFC%20%E8%A7%84%E8%8C%83%E5%8C%96%20%2B%20casefold%22%5D%0A%20%20B%20--%3E%20C%5B%22Script%20%E6%AD%A3%E5%88%99%E9%A2%84%E5%88%87%E5%88%86%22%5D%0A%20%20C%20--%3E%20D%5B%22byte-level%20BPE%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20D%20--%3E%20E%7B%22%E8%AF%8D%E8%A1%A8%E8%A7%81%E8%BF%87%3F%22%7D%0A%20%20E%20--%3E%7C%22%E5%A4%9A%E5%AD%97%E8%8A%82%E5%90%88%E8%AF%8D%22%7C%20F%5B%22%E4%BD%8E%20fertility%20token%22%5D%0A%20%20E%20--%3E%7C%22%E6%9C%AA%E8%A7%81%22%7C%20G%5B%22%E5%AD%97%E8%8A%82%E5%9B%9E%E9%80%80%3A%20%E6%B0%B8%E4%B8%8D%20OOV%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：Unicode 像「同一道菜的三种写法」——「宫保鸡丁」「宫保雞丁」「gong bao ji ding」，菜相同、字面全异；入口规范化是「先统一成简体再进后厨」，字节回退是「不认识的字就按笔画逐笔拼」——保证能下单，只是慢且贵。")],-1)),e[4]||(e[4]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=t("p",null,[n("机制核心：BPE 的合并统计由"),t("strong",null,"训练语料的编码形态"),n("决定，词表学到的不是「字」而是「语料中高频的字节对」。英语主导语料里，中文单字从未高频出现 → 中文 fertility 低；等价形未归一 → 语料里 NFC/NFD 各占一半 → 两套 token 都学了个半吊子。Zalgo 攻击的机制同源：组合符可以无限叠加，字节回退让 100 个组合符 = 数百 token = 数百倍账单与上下文占用——这是安全漏洞不只是质量问题。Petrov et al. 的实测：同一语义任务，非拉丁语言的推理成本与延迟数倍于英语，且准确率因「上下文窗口被 token 垃圾挤占」而下降。")],-1)),(o(),r(s,null,{default:a(()=>[l(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%E8%8B%B1%E8%AF%AD%E8%AF%8D%E8%A1%A8%E4%BC%A4%E5%A4%9A%E8%AF%AD%3F%22%7D%20--%3E%20R%5B%22BPE%20%E5%AD%A6%E7%9A%84%E6%98%AF%E8%AF%AD%E6%96%99%E9%AB%98%E9%A2%91%E5%AD%97%E8%8A%82%E5%AF%B9%22%5D%0A%20%20R%20--%3E%20S%5B%22%E4%B8%AD%E6%96%87%E5%8D%95%E5%AD%97%E4%BD%8E%E9%A2%91%20%E2%86%92%20%E5%AD%97%E8%8A%82%E5%9B%9E%E9%80%80%22%5D%0A%20%20S%20--%3E%20T%5B%22fertility%200.3-0.5%20%E2%86%92%20token%C3%973%22%5D%0A%20%20U%7B%22%E7%AD%89%E4%BB%B7%E5%BD%A2%E4%B8%BA%E4%BD%95%E6%9C%89%E5%AE%B3%3F%22%7D%20--%3E%20V%5B%22NFC%2FNFD%20%E5%AD%97%E8%8A%82%E4%B8%8D%E5%90%8C%22%5D%0A%20%20V%20--%3E%20W%5B%22token%20%E4%B8%8D%E5%90%8C%20%E2%86%92%20%E6%A3%80%E7%B4%A2%2F%E8%AF%84%E6%B5%8B%E9%94%99%E4%BD%8D%22%5D%0A%20%20T%20--%3E%20X%5B%22%E6%88%90%E6%9C%AC%E3%80%81%E5%BB%B6%E8%BF%9F%E3%80%81%E8%B4%A8%E9%87%8F%E4%B8%89%E8%BE%93%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">常见误区：以为「byte-level = 万能」——它保证合法性与可逆性，不保证效率与公平；另一误区是训练前后归一化不一致：训练语料 NFC、推理输入 NFD，同一个词走两条 token 路径，模型表现像「没见过这个词」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>规范化不是免费的：德语 ß 与 ss 的 casefold 合并、日文片假名长音符号的历史歧义，说明「统一形态」本身就是语言学决策。多语模型的正解是<strong>语料配额</strong>（保证每语言高频 n-gram 进词表）而非纯技术修补；tokenizer 换代是破坏性变更——词表即模型的骨骼。与<a href="/llm/attention-mask-padding">注意力掩码与填充</a>的接续：token 化之后，batch 里长短不一的序列靠 padding 对齐，掩码的坑接踵而来——坑从字节一路埋到张量。</p><p><span class="marginnote">直觉类比：tokenizer 像海关，byte-level BPE 是「人不认识也放行」的最低海关——任何旅客（字节串）都能入境；但无签证（未见 n-gram）者被逐件开箱（按字节拆），通关时间（token 数）翻十倍，且开箱期间占满候机厅（上下文窗口）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Unicode 三坑：等价形、fertility 不公、规范化不一致。</li><li>防坑四件套：NFC 入口、byte 回退、Script 预切分、评测归一化。</li><li>token 不公平 = 成本/延迟/质量的三重放大器。</li><li>出处：Petrov et al. 2023；GPT-4 tiktoken 实现；Unicode Standard Annex #15。</li></ul>',6))])}const C=A(D,[["render",p]]);export{u as __pageData,C as default};
